// Unicode helpers matching CPython semantics (code points, not UTF-16 units).

export function codePoints(str) {
  const out = [];
  for (const ch of str) out.push(ch.codePointAt(0));
  return out;
}

export function pyLen(str) {
  let n = 0;
  for (const _ of str) n++;
  return n;
}

export function fromCodePoints(cps) {
  let out = '';
  for (let i = 0; i < cps.length; i += 1024) {
    out += String.fromCodePoint(...cps.slice(i, i + 1024));
  }
  return out;
}

const NONPRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

// Python str.isprintable() for a single code point.
export function isPyPrintable(cp) {
  if (cp === 0x20) return true;
  return !NONPRINTABLE.test(String.fromCodePoint(cp));
}

// The non-ASCII code points int() folds to U+0020.
const INT_SPACE = new Set([
  0x0085, 0x00a0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

export function isPyIntSpace(cp) {
  return INT_SPACE.has(cp);
}

// C isspace(): the only code points int() strips.
export function isAsciiCSpace(cp) {
  return cp === 0x09 || cp === 0x0a || cp === 0x0b || cp === 0x0c || cp === 0x0d || cp === 0x20;
}

const ND = /\p{Nd}/u;

// Decimal value of a General_Category=Nd code point, else null.
export function ndDigitValue(cp) {
  if (cp > 0x10ffff || cp < 0) return null;
  if (!ND.test(String.fromCodePoint(cp))) return null;
  let start = cp;
  while (start > 0 && ND.test(String.fromCodePoint(start - 1))) start--;
  return (cp - start) % 10;
}

export function isDecimalDigitCp(cp) {
  return ndDigitValue(cp) !== null;
}

// Python codec behaviours: surrogateescape decode, strict UTF-8 encode, backslashreplace.

import { fromCodePoints } from './unicode.mjs';

// Byte-by-byte resync decoder: one lone surrogate per undecodable byte.
export function decodeSurrogateEscape(bytes) {
  const n = bytes.length;
  const cps = [];
  let i = 0;
  while (i < n) {
    const b = bytes[i];
    if (b < 0x80) { cps.push(b); i++; continue; }
    let seq = 0;
    if (b >= 0xc2 && b <= 0xdf) seq = 2;
    else if (b >= 0xe0 && b <= 0xef) seq = 3;
    else if (b >= 0xf0 && b <= 0xf4) seq = 4;

    let ok = seq !== 0 && i + seq <= n;
    if (ok) {
      for (let k = 1; k < seq; k++) {
        const c = bytes[i + k];
        if (c < 0x80 || c > 0xbf) { ok = false; break; }
      }
    }
    if (ok) {
      const b1 = bytes[i + 1];
      if (b === 0xe0 && b1 < 0xa0) ok = false;
      else if (b === 0xed && b1 > 0x9f) ok = false;
      else if (b === 0xf0 && b1 < 0x90) ok = false;
      else if (b === 0xf4 && b1 > 0x8f) ok = false;
    }
    if (ok) {
      let cp;
      if (seq === 2) cp = ((b & 0x1f) << 6) | (bytes[i + 1] & 0x3f);
      else if (seq === 3) cp = ((b & 0x0f) << 12) | ((bytes[i + 1] & 0x3f) << 6) | (bytes[i + 2] & 0x3f);
      else cp = ((b & 0x07) << 18) | ((bytes[i + 1] & 0x3f) << 12) | ((bytes[i + 2] & 0x3f) << 6) | (bytes[i + 3] & 0x3f);
      cps.push(cp);
      i += seq;
    } else {
      cps.push(0xdc00 + b);
      i += 1;
    }
  }
  return fromCodePoints(cps);
}

function pushUtf8(out, cp) {
  if (cp < 0x80) out.push(cp);
  else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
  else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
}

// Python str.encode('utf-8') with strict errors; reports the FIRST surrogate run.
export function encodeUtf8Strict(str) {
  const out = [];
  let k = 0;
  const cps = [];
  for (const ch of str) cps.push(ch.codePointAt(0));
  while (k < cps.length) {
    const cp = cps[k];
    if (cp >= 0xd800 && cp <= 0xdfff) {
      let end = k;
      while (end + 1 < cps.length && cps[end + 1] >= 0xd800 && cps[end + 1] <= 0xdfff) end++;
      return { ok: false, start: k, end, cp };
    }
    pushUtf8(out, cp);
    k++;
  }
  return { ok: true, bytes: Uint8Array.from(out) };
}

// Python's errors='backslashreplace' on a UTF-8 stream.
export function encodeBackslashReplace(str) {
  const out = [];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp >= 0xd800 && cp <= 0xdfff) {
      const text = '\\u' + cp.toString(16).padStart(4, '0');
      for (let i = 0; i < text.length; i++) out.push(text.charCodeAt(i));
    } else {
      pushUtf8(out, cp);
    }
  }
  return Uint8Array.from(out);
}

// CPython int(str) semantics.

import { isPyIntSpace, isAsciiCSpace, ndDigitValue } from './unicode.mjs';

const SHAPE = /^[+-]?[0-9](_?[0-9])*$/;
const MAX_DIGITS = 4300;

export function pyInt(str) {
  const mapped = [];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp < 0x7f) { mapped.push(cp); continue; }
    if (isPyIntSpace(cp)) { mapped.push(0x20); continue; }
    const d = ndDigitValue(cp);
    mapped.push(d === null ? cp : 0x30 + d);
  }

  let lo = 0;
  let hi = mapped.length;
  while (lo < hi && isAsciiCSpace(mapped[lo])) lo++;
  while (hi > lo && isAsciiCSpace(mapped[hi - 1])) hi--;
  const core = mapped.slice(lo, hi);
  if (core.length === 0) return { ok: false };
  if (core.some((cp) => cp > 0xffff)) return { ok: false };

  const s = String.fromCharCode(...core);
  if (!SHAPE.test(s)) return { ok: false };

  let digits = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0x30 && c <= 0x39) digits++;
  }
  if (digits > MAX_DIGITS) return { ok: false };

  return { ok: true, value: BigInt(s.split('_').join('')) };
}

// CPython repr(str).

import { isPyPrintable } from './unicode.mjs';

export function pyStrRepr(str) {
  let hasSQ = false;
  let hasDQ = false;
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp === 0x27) hasSQ = true;
    else if (cp === 0x22) hasDQ = true;
  }
  const delim = hasSQ && !hasDQ ? '"' : "'";

  let out = delim;
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp === 0x27 && delim === "'") out += "\\'";
    else if (cp === 0x5c) out += '\\\\';
    else if (cp === 0x09) out += '\\t';
    else if (cp === 0x0a) out += '\\n';
    else if (cp === 0x0d) out += '\\r';
    else if (isPyPrintable(cp)) out += ch;
    else if (cp <= 0xff) out += '\\x' + cp.toString(16).padStart(2, '0');
    else if (cp <= 0xffff) out += '\\u' + cp.toString(16).padStart(4, '0');
    else out += '\\U' + cp.toString(16).padStart(8, '0');
  }
  return out + delim;
}

// CPython repr(bytes). Output is always pure ASCII.

export function pyBytesRepr(bytes) {
  let hasSQ = false;
  let hasDQ = false;
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] === 0x27) hasSQ = true;
    else if (bytes[i] === 0x22) hasDQ = true;
  }
  const delim = hasSQ && !hasDQ ? '"' : "'";

  let out = 'b' + delim;
  for (let i = 0; i < bytes.length; i++) {
    const c = bytes[i];
    if (c === 0x27 && delim === "'") out += "\\'";
    else if (c === 0x5c) out += '\\\\';
    else if (c === 0x09) out += '\\t';
    else if (c === 0x0a) out += '\\n';
    else if (c === 0x0d) out += '\\r';
    else if (c < 0x20 || c >= 0x7f) out += '\\x' + c.toString(16).padStart(2, '0');
    else out += String.fromCharCode(c);
  }
  return out + delim;
}

// Synchronous raw-byte writes to fd 1/2 so nothing is lost on exit.

import { writeSync } from 'node:fs';
import process from 'node:process';

import { encodeBackslashReplace } from '../py/codec.mjs';

export function writeBytes(fd, bytes) {
  const data = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);
  let off = 0;
  while (off < data.length) {
    let written;
    try {
      written = writeSync(fd, data, off, data.length - off);
    } catch (e) {
      if (e && (e.code === 'EAGAIN' || e.code === 'EINTR')) continue;
      if (e && e.code === 'EPIPE') return;
      throw e;
    }
    if (written <= 0) break;
    off += written;
  }
}

export function writeStdoutBytes(bytes) {
  writeBytes(1, bytes);
}

export function writeStderrBytes(bytes) {
  writeBytes(2, bytes);
}

export function writeStderrPyText(str) {
  writeStderrBytes(encodeBackslashReplace(str));
}

export function writeStdoutAscii(str) {
  const out = new Uint8Array(str.length);
  for (let i = 0; i < str.length; i++) out[i] = str.charCodeAt(i) & 0xff;
  writeStdoutBytes(out);
}

export function exitWith(code) {
  process.exit(code);
}

// Recover raw argv bytes from /proc/self/cmdline; process.argv is lossy for invalid UTF-8.

import { readFileSync } from 'node:fs';
import process from 'node:process';

function fallback() {
  const enc = new TextEncoder();
  return process.argv.slice(2).map((s) => enc.encode(s));
}

export function getArgvByteArrays() {
  const want = process.argv.length - 2;
  if (want < 0) return fallback();
  if (want === 0) return [];

  let bytes;
  try {
    bytes = Uint8Array.from(readFileSync('/proc/self/cmdline'));
  } catch {
    return fallback();
  }

  const entries = [];
  let start = 0;
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] === 0) { entries.push(bytes.slice(start, i)); start = i + 1; }
  }
  if (start < bytes.length) entries.push(bytes.slice(start));

  if (entries.length < want) return fallback();
  const tail = entries.slice(entries.length - want);

  const dec = new TextDecoder('utf-8');
  for (let i = 0; i < want; i++) {
    if (dec.decode(tail[i]) !== process.argv[i + 2]) return fallback();
  }
  return tail;
}

// Static parser description: prog name, option table, lookup orders.

export const PROG = 'test8_executable';

export const OPTIONS = [
  { dest: 'help', optionStrings: ['-h', '--help'], nargs: 0, metavar: null, type: null, required: false, help: 'show this help message and exit' },
  { dest: 'a', optionStrings: ['--a'], nargs: 1, metavar: 'A', type: 'int', required: true, help: '' },
  { dest: 'b', optionStrings: ['--b'], nargs: 1, metavar: 'B', type: 'int', required: true, help: '' },
  { dest: 'c', optionStrings: ['--c'], nargs: 1, metavar: 'C', type: 'str', required: true, help: '' },
];

export const OPTION_STRING_ORDER = ['-h', '--help', '--a', '--b', '--c'];
export const LONG_OPTION_ORDER = ['--help', '--a', '--b', '--c'];

const BY_STRING = new Map();
for (const action of OPTIONS) {
  for (const s of action.optionStrings) BY_STRING.set(s, action);
}

export function actionForOptionString(s) {
  return BY_STRING.get(s) || null;
}

export function actionName(action) {
  return action.optionStrings.join('/');
}

export const USAGE_BODY = '[-h] --a A --b B --c C';
export const HELP_TEXT = 'show this help message and exit';
export const ACTION_MAX_LENGTH = 12;

// Control-flow signals raised by the parser.

export class HelpRequested extends Error {
  constructor() {
    super('help requested');
    this.name = 'HelpRequested';
  }
}

export class ArgparseError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgparseError';
  }
}

// argparse HelpFormatter: terminal width, usage line, options block.

import process from 'node:process';

import { PROG, OPTIONS, USAGE_BODY, HELP_TEXT, ACTION_MAX_LENGTH } from './spec.mjs';

const PREFIX = 'usage: ';

export function terminalColumns() {
  const raw = process.env.COLUMNS;
  if (raw !== undefined && /^[+-]?[0-9]+$/.test(raw.trim())) {
    const n = Number.parseInt(raw.trim(), 10);
    if (n >= 1) return n;
  }
  return 80;
}

export function formatterWidth() {
  return terminalColumns() - 2;
}

function getLines(parts, indent, width, withPrefix) {
  const lines = [];
  let line = [];
  let lineLen = (withPrefix ? PREFIX.length : indent.length) - 1;
  for (const part of parts) {
    if (lineLen + 1 + part.length > width && line.length) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length) lines.push(indent + line.join(' '));
  if (withPrefix && lines.length) lines[0] = lines[0].slice(indent.length);
  return lines;
}

export function formatUsage(width) {
  const usage = PROG + ' ' + USAGE_BODY;
  if (PREFIX.length + usage.length <= width) return PREFIX + usage;

  const parts = USAGE_BODY.split(/\s+/).filter((s) => s.length);
  let lines;
  if (PREFIX.length + PROG.length <= 0.75 * width) {
    const indent = ' '.repeat(PREFIX.length + PROG.length + 1);
    lines = getLines([PROG, ...parts], indent, width, true);
  } else {
    const indent = ' '.repeat(PREFIX.length);
    lines = [PROG, ...getLines(parts, indent, width, false)];
  }
  return PREFIX + lines.join('\n');
}

function wrapText(text, width) {
  const words = text.split(/\s+/).filter((s) => s.length);
  const lines = [];
  let line = '';
  for (const w of words) {
    if (line === '') line = w;
    else if (line.length + 1 + w.length <= width) line += ' ' + w;
    else { lines.push(line); line = w; }
  }
  if (line !== '') lines.push(line);
  return lines;
}

function invocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((s) => s + ' ' + action.metavar).join(', ');
}

export function formatHelp(width) {
  const maxHelpPosition = Math.min(24, Math.max(width - 20, 4));
  const helpPosition = Math.min(ACTION_MAX_LENGTH + 2, maxHelpPosition);
  const helpWidth = Math.max(width - helpPosition, 11);
  const actionWidth = helpPosition - 2 - 2;

  let rows = '';
  for (const action of OPTIONS) {
    const header = invocation(action);
    const help = action.dest === 'help' ? HELP_TEXT : action.help;
    if (!help || !help.trim()) {
      rows += '  ' + header + '\n';
      continue;
    }
    const lines = wrapText(help, helpWidth);
    if (header.length <= actionWidth) {
      rows += '  ' + header.padEnd(actionWidth) + '  ' + lines[0] + '\n';
    } else {
      rows += '  ' + header + '\n';
      rows += ' '.repeat(helpPosition) + lines[0] + '\n';
    }
    for (const line of lines.slice(1)) {
      rows += ' '.repeat(helpPosition) + line + '\n';
    }
  }

  const text = formatUsage(width) + '\n\n' + 'options:\n' + rows;
  return text.replace(/^\n+/, '').replace(/\n+$/, '') + '\n';
}

// argparse token classification, pre-pass and left-to-right consumption.

import { pyStrRepr } from '../py/strRepr.mjs';
import { pyInt } from '../py/intParse.mjs';
import { isDecimalDigitCp } from '../py/unicode.mjs';
import { HelpRequested, ArgparseError } from './errors.mjs';
import { OPTION_STRING_ORDER, actionForOptionString, actionName } from './spec.mjs';

const PREFIX_CHARS = '-';

function isPrefixChar(ch) {
  return ch !== undefined && PREFIX_CHARS.includes(ch);
}

// Python's _negative_number_matcher: ^-\d+$|^-\d*\.\d+$ with Unicode Nd.
function looksLikeNegativeNumber(t) {
  const cps = [];
  for (const ch of t) cps.push(ch.codePointAt(0));
  if (cps.length < 2 || cps[0] !== 0x2d) return false;
  let i = 1;
  let digits = 0;
  while (i < cps.length && isDecimalDigitCp(cps[i])) { i++; digits++; }
  if (i === cps.length) return digits > 0;
  if (cps[i] !== 0x2e) return false;
  i++;
  let frac = 0;
  while (i < cps.length && isDecimalDigitCp(cps[i])) { i++; frac++; }
  return i === cps.length && frac > 0;
}

function getOptionTuples(t) {
  const result = [];
  if (isPrefixChar(t[0]) && isPrefixChar(t[1])) {
    const eq = t.indexOf('=');
    const optionPrefix = eq === -1 ? t : t.slice(0, eq);
    const sep = eq === -1 ? null : '=';
    const explicitArg = eq === -1 ? null : t.slice(eq + 1);
    for (const s of OPTION_STRING_ORDER) {
      if (s.startsWith(optionPrefix)) {
        result.push({ action: actionForOptionString(s), optionString: s, sep, explicitArg });
      }
    }
  } else if (isPrefixChar(t[0]) && !isPrefixChar(t[1])) {
    const shortPrefix = t.slice(0, 2);
    const shortExplicit = t.slice(2);
    for (const s of OPTION_STRING_ORDER) {
      if (s === shortPrefix) {
        result.push({ action: actionForOptionString(s), optionString: s, sep: '', explicitArg: shortExplicit });
      } else if (s.startsWith(t)) {
        result.push({ action: actionForOptionString(s), optionString: s, sep: null, explicitArg: null });
      }
    }
  }
  return result;
}

// null => positional; otherwise an option tuple (action null => unknown option).
function parseOptional(t) {
  if (t === '') return null;
  if (!isPrefixChar(t[0])) return null;

  const exact = actionForOptionString(t);
  if (exact) return { action: exact, optionString: t, sep: null, explicitArg: null };

  if (t.length === 1) return null;

  const eq = t.indexOf('=');
  if (eq !== -1) {
    const head = t.slice(0, eq);
    const headAction = actionForOptionString(head);
    if (headAction) {
      return { action: headAction, optionString: head, sep: '=', explicitArg: t.slice(eq + 1) };
    }
  }

  const tuples = getOptionTuples(t);
  if (tuples.length > 1) {
    const matches = tuples.map((x) => x.optionString).join(', ');
    throw new ArgparseError('ambiguous option: ' + t + ' could match ' + matches);
  }
  if (tuples.length === 1) return tuples[0];

  if (looksLikeNegativeNumber(t)) return null;
  if (t.includes(' ')) return null;

  return { action: null, optionString: t, sep: null, explicitArg: null };
}

function prePass(argStrings) {
  const pattern = [];
  const tuples = new Map();
  for (let i = 0; i < argStrings.length; i++) {
    if (argStrings[i] === '--') {
      pattern.push('-');
      for (let j = i + 1; j < argStrings.length; j++) pattern.push('A');
      break;
    }
    const tuple = parseOptional(argStrings[i]);
    if (tuple === null) {
      pattern.push('A');
    } else {
      tuples.set(i, tuple);
      pattern.push('O');
    }
  }
  return { pattern, tuples };
}

function convert(action, optionString, value) {
  if (action.type !== 'int') return value;
  const parsed = pyInt(value);
  if (!parsed.ok) {
    throw new ArgparseError('argument ' + optionString + ': invalid int value: ' + pyStrRepr(value));
  }
  return parsed.value;
}

export function parseArgs(argStrings) {
  const { pattern, tuples } = prePass(argStrings);
  const values = {};
  const extras = [];
  const n = argStrings.length;

  let i = 0;
  while (i < n) {
    if (pattern[i] !== 'O') {
      // positional region: nothing consumes it, so it becomes an extra
      extras.push(argStrings[i]);
      i++;
      continue;
    }

    let { action, optionString, sep, explicitArg } = tuples.get(i);
    if (action === null) {
      extras.push(argStrings[i]);
      i++;
      continue;
    }

    const pending = [];
    let stop = i + 1;
    for (;;) {
      if (explicitArg !== null) {
        if (action.nargs === 0) {
          if (explicitArg !== '' && !isPrefixChar(optionString[1])) {
            if (sep || isPrefixChar(explicitArg[0])) {
              throw new ArgparseError('argument ' + actionName(action) + ': ignored explicit argument ' + pyStrRepr(explicitArg));
            }
            pending.push({ action, args: [], optionString });
            const char = optionString[0];
            optionString = char + explicitArg[0];
            const next = actionForOptionString(optionString);
            if (next) {
              action = next;
              explicitArg = explicitArg.slice(1);
              if (explicitArg === '') { sep = null; explicitArg = null; }
              else if (explicitArg[0] === '=') { sep = '='; explicitArg = explicitArg.slice(1); }
              else sep = '';
              continue;
            }
            extras.push(char + explicitArg);
            stop = i + 1;
            break;
          }
          throw new ArgparseError('argument ' + actionName(action) + ': ignored explicit argument ' + pyStrRepr(explicitArg));
        }
        pending.push({ action, args: [explicitArg], optionString });
        stop = i + 1;
        break;
      }

      if (action.nargs === 0) {
        pending.push({ action, args: [], optionString });
        stop = i + 1;
        break;
      }

      if (i + 1 < n && pattern[i + 1] === 'A') {
        pending.push({ action, args: [argStrings[i + 1]], optionString });
        stop = i + 2;
        break;
      }
      throw new ArgparseError('argument ' + optionString + ': expected one argument');
    }

    for (const taken of pending) {
      if (taken.action.dest === 'help') throw new HelpRequested();
      values[taken.action.dest] = convert(taken.action, taken.optionString, taken.args[0]);
    }
    i = stop;
  }

  const missing = [];
  for (const dest of ['a', 'b', 'c']) {
    if (!(dest in values)) missing.push('--' + dest);
  }
  if (missing.length) {
    throw new ArgparseError('the following arguments are required: ' + missing.join(', '));
  }

  if (extras.length) {
    throw new ArgparseError('unrecognized arguments: ' + extras.join(' '));
  }

  return { a: values.a, b: values.b, c: values.c };
}

// construct exception value objects.

export class FormatFieldError extends Error {
  constructor(valueDecimal) {
    super('struct error during building');
    this.name = 'FormatFieldError';
    this.valueDecimal = valueDecimal;
  }
}

export class StreamError extends Error {
  constructor(expected, found) {
    super('bytes object of wrong length');
    this.name = 'StreamError';
    this.expected = expected;
    this.found = found;
  }
}

// construct.Int8ul.build

import { FormatFieldError } from './errors.mjs';

export function buildInt8ul(value) {
  if (value < 0n || value > 255n) throw new FormatFieldError(value.toString());
  return Uint8Array.of(Number(value));
}

